namespace PZ3D {
 sealed class ModernController:IDisposable {
  readonly object gate=new object();readonly bool test;readonly string user,data;
  readonly LauncherJournal journal;Engine engine;ServerProfiles servers;bool busy,disposed;CancellationTokenSource cancel=new CancellationTokenSource();
  int progressValue=-1;string progressText="就绪";readonly List<string> log=new List<string>();
  readonly Dictionary<string,ViewpointSettings> settingSnapshots=new Dictionary<string,ViewpointSettings>();
  readonly Dictionary<string,ShaderSelection> shaderSnapshots=new Dictionary<string,ShaderSelection>();
  readonly HashSet<string> memorySnapshots=new HashSet<string>();
  readonly Func<Engine,ulong[],Action<int,string>,CancellationToken,bool,Dictionary<ulong,string>> fetch;
  readonly Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object> networkFetch;
  readonly SemaphoreSlim networkLane=new SemaphoreSlim(1,1);readonly List<CancellationTokenSource> networkRequests=new List<CancellationTokenSource>();CancellationTokenSource hallRequest;
  sealed class HallReceipt {public long Order;public string Id;}
  long hallOrder;string hallReceiptId="";
  public static readonly HashSet<string> NativeNetworkReads=new HashSet<string>{"steamConnection","steamSubscriptions","steamSearch","steamDetails","serverHall","serverQuery","updatesGet"};
  public Action<int,string> Progress;
  public Action<string,object> Event;
  public bool Busy{get{lock(gate)return busy||networkRequests.Count>0;}}
  public bool NetworkBusy{get{lock(gate)return networkRequests.Count>0;}}
  public ModernController(string game,string user,string data,bool test=false):this(game,user,data,test,null){}
  internal ModernController(string game,string user,string data,bool test,Func<Engine,ulong[],Action<int,string>,CancellationToken,bool,Dictionary<ulong,string>> download):this(game,user,data,test,download,null){}
  internal ModernController(string game,string user,string data,bool test,Func<Engine,ulong[],Action<int,string>,CancellationToken,bool,Dictionary<ulong,string>> download,Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object> network){this.user=Path.GetFullPath(user);this.data=Path.GetFullPath(data);this.test=test;journal=new LauncherJournal(this.data);fetch=download??Download;networkFetch=network??((e,a,p,progress,token,batch)=>a=="serverQuery"?servers.Query(Text(p,"id"),token):a=="updatesGet"?ComponentEvidence.CheckUpdates(e,token):SteamLauncherServices.Execute(e,a,p,progress,token,batch));SetEngine(game);}
  void SetEngine(string game){engine=new Engine(string.IsNullOrWhiteSpace(game)?Path.Combine(data,"unselected-game"):game,user,data,test);servers=new ServerProfiles(data);engine.Progress=(v,t)=>Report(v,t);ApplySources();settingSnapshots.Clear();shaderSnapshots.Clear();memorySnapshots.Clear();}
  void ApplySources(){engine.BuddySource=InstallWorkflow.Source(engine,3619862853);engine.ViewSource=InstallWorkflow.Source(engine,3809306528);engine.ModelsSource=InstallWorkflow.Source(engine,3810302175);}
  static string Text(Dictionary<string,object> p,string key){object v;if(!p.TryGetValue(key,out v)||!(v is string))throw new Exception("缺少有效参数："+key);return (string)v;}
  static bool Flag(Dictionary<string,object> p,string key){object v;return p.TryGetValue(key,out v)&&v is bool&&(bool)v;}
  static void Confirm(Dictionary<string,object> p){if(!Flag(p,"confirmed"))throw new Exception("操作需要明确确认。");}
  static object Message(string message){return new{message=message};}
  bool Running(){return !test&&GameProcessGuard.IsRunning(engine.Game);}
  public void AssertCanRestart(){lock(gate){if(busy||networkRequests.Count!=0)throw new InvalidOperationException("本机任务仍在结束，请稍后重试。");if(Running())throw new InvalidOperationException("请先退出游戏再更新启动器。");if(LaunchProfiles.Pending(engine))throw new InvalidOperationException("启动会话尚未恢复，请先恢复本地模组清单。");}}
  void Report(int value,string text){journal.Update(value,text);lock(gate){progressValue=value;progressText=text;}var callback=Progress;if(callback!=null)callback(value,text);}
  void Check(){cancel.Token.ThrowIfCancellationRequested();foreach(string path in new[]{engine.Game,engine.Config,engine.Mods,user,data})LauncherMaintenance.NoReparse(path);if(LaunchProfiles.Pending(engine))throw new Exception("启动会话尚未恢复，请退出游戏并刷新状态后再修改。");engine.Guard();}
  public void Cancel(){lock(gate){if(!disposed){cancel.Cancel();foreach(var request in networkRequests)request.Cancel();}}}
  public static bool IsHallCancel(string action,Dictionary<string,object> payload){object scope;return action=="cancel"&&payload!=null&&payload.TryGetValue("scope",out scope)&&scope is string&&(string)scope=="hall";}
  void CancelHall(string requestId){lock(gate){if(!disposed&&hallReceiptId==requestId){hallOrder++;hallReceiptId="";if(hallRequest!=null)hallRequest.Cancel();}}}
  static string NetworkId(Dictionary<string,object> payload){object raw;string id=payload.TryGetValue("requestId",out raw)?raw as string:Guid.NewGuid().ToString("N");if(string.IsNullOrEmpty(id)||id.Length>80||!Regex.IsMatch(id,@"^[A-Za-z0-9_-]+$"))throw new Exception("网络请求标识无效。");return id;}
  public void ReserveHall(Dictionary<string,object> payload){string id=NetworkId(payload);lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");hallReceiptId=id;payload["requestId"]=id;payload["_hallReceipt"]=new HallReceipt{Order=++hallOrder,Id=id};if(hallRequest!=null)hallRequest.Cancel();}}
  void DrainNetworkBeforeLaunch(){lock(gate){hallOrder++;hallReceiptId="";foreach(var request in networkRequests)request.Cancel();}var watch=Stopwatch.StartNew();while(true){cancel.Token.ThrowIfCancellationRequested();lock(gate)if(networkRequests.Count==0)return;if(watch.ElapsedMilliseconds>7000)throw new Exception("Steam 查询尚未释放，未启动游戏。请稍后重试。");Thread.Sleep(20);}}
  object ExecuteNetwork(string action,Dictionary<string,object> payload){
   payload=payload??new Dictionary<string,object>();object receiptValue;HallReceipt receipt=null;if(action=="serverHall"){if(!payload.TryGetValue("_hallReceipt",out receiptValue)||!(receiptValue is HallReceipt))ReserveHall(payload);receipt=(HallReceipt)payload["_hallReceipt"];}string requestId=NetworkId(payload);
   var tokenSource=new CancellationTokenSource();Engine selected;
   lock(gate){if(disposed){tokenSource.Dispose();throw new ObjectDisposedException("ModernController");}if(busy){tokenSource.Dispose();throw new Exception("正在修改本地文件，请完成后再查询网络。");}if(receipt!=null&&(receipt.Order!=hallOrder||receipt.Id!=requestId)){tokenSource.Dispose();throw new OperationCanceledException("已忽略被刷新替代的大厅请求。");}if(networkRequests.Count>=16){tokenSource.Dispose();throw new Exception("等待的网络请求过多，请稍后重试。");}selected=engine;if(action=="serverHall")hallRequest=tokenSource;networkRequests.Add(tokenSource);}
   bool acquired=false;
   try{if(action.StartsWith("steam",StringComparison.Ordinal)||action=="serverHall"){networkLane.Wait(tokenSource.Token);acquired=true;}tokenSource.Token.ThrowIfCancellationRequested();var result=networkFetch(selected,action=="serverHall"?"hall":action.StartsWith("steam",StringComparison.Ordinal)?action.Substring(5).ToLowerInvariant():action,payload,(v,t)=>{var callback=Event;if(callback!=null)callback("networkProgress",new{requestId=requestId,value=v,text=t});},tokenSource.Token,batch=>{tokenSource.Token.ThrowIfCancellationRequested();var node=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(batch));object rows;if(!node.TryGetValue("servers",out rows))throw new Exception("大厅增量响应缺少服务器列表。");var callback=Event;if(callback!=null)callback("hallBatch",new{requestId=requestId,servers=rows});});tokenSource.Token.ThrowIfCancellationRequested();return result;}
   catch(Exception ex){try{journal.Diagnostic(action+" · 网络读取未完成 · "+ex.Message);}catch{}throw;}
   finally{if(acquired)networkLane.Release();lock(gate){networkRequests.Remove(tokenSource);if(hallRequest==tokenSource)hallRequest=null;}tokenSource.Dispose();}
  }
  public object Execute(string action,Dictionary<string,object> payload){
   if(action=="taskGet")return journal.Snapshot();if(action=="playtimeGet")return PlaytimeTracker.Snapshot(data);
   if(action=="cancel"){if(IsHallCancel(action,payload)){CancelHall(Text(payload,"requestId"));return Message("已停止指定大厅查询，已收到的列表保留。");}Cancel();return Message("已请求取消；当前安全文件阶段完成后停止。");}
   if(NativeNetworkReads.Contains(action))return ExecuteNetwork(action,payload);
   lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");if(action=="setGame"&&networkRequests.Count>0)throw new Exception("网络查询进行中，不能切换安装目录；请取消查询后再选择。");if(busy)throw new Exception("正在执行任务，请等待完成或取消。");busy=true;cancel.Dispose();cancel=new CancellationTokenSource();}
   bool mutation=!NativeReads.Contains(action);
   try{if(mutation){journal.Begin(action,TaskTitle(action,payload));Report(-1,"正在处理 "+TaskTitle(action,payload));}if(action=="launch"||action=="profileLaunch")DrainNetworkBeforeLaunch();object result=Dispatch(action,payload??new Dictionary<string,object>());if(mutation){string message=SafeResultMessage(result,TaskTitle(action,payload));lock(gate){log.Add(DateTime.Now.ToString("HH:mm:ss")+" "+message);if(log.Count>100)log.RemoveAt(0);}bool partial=message.Contains("[失败]");journal.Finish(partial?"partial":"completed",message);Report(partial?-1:100,partial?"部分完成；请核对各组件失败原因和当前配置。":"操作完成；游戏内效果仍需验证");}return result;}
   catch(Exception ex){if(!mutation){try{journal.Diagnostic(action+" · 读取失败 · "+ex.Message);}catch{}}if(mutation){journal.Finish(ex is OperationCanceledException?"cancelled":"failed",ex.Message);lock(gate){log.Add(DateTime.Now.ToString("HH:mm:ss")+" "+LauncherJournal.Sanitize(ex.Message));}Report(-1,ex is OperationCanceledException?"任务已取消":ex.Message);}throw;}
   finally{lock(gate)busy=false;}
  }
  public void RecoverStartup(){try{string recovered=LaunchProfiles.Recover(engine);if(recovered!="")lock(gate)log.Add(recovered);}catch(Exception ex){lock(gate)log.Add("启动恢复未完成："+ex.Message);}}
  object Dispatch(string action,Dictionary<string,object> p){switch(action){
   case "status":return Status();
   case "modProfiles":return ModConfigurations.List(engine);
   case "modProfileGet":return ModConfigurations.Read(engine,Text(p,"id"));
   case "modProfileSave":Check();return ModConfigurations.Save(engine,p);
   case "modProfileDelete":Check();return ModConfigurations.Delete(engine,Text(p,"id"),Text(p,"stamp"));
   case "modProfileActivate":Check();return ModConfigurations.Activate(engine,Text(p,"id"),Text(p,"stamp"),Flag(p,"confirmed"));
   case "modSort":return ModConfigurations.Sort(engine,ModArray(p));
   case "saveThumb":return LauncherPictures.Save(engine,Text(p,"id"));
   case "serverThumb":return LauncherPictures.Server(engine,servers.Target(Text(p,"id")));
   case "serverFavorites":return GameFavorites.List(engine);
   case "favoriteImport":return GameFavorites.Import(engine,servers,Text(p,"id"),Flag(p,"confirmed"));
   case "playtimeSettings":return PlaytimeTracker.Settings(data,p);
   case "steamConnection":case "steamSubscriptions":case "steamSearch":case "steamDetails":case "serverHall":return SteamLauncherServices.Execute(engine,action=="serverHall"?"hall":action.Substring(5).ToLowerInvariant(),p,Report,cancel.Token);
   case "steamDownload":Confirm(p);Check();return SteamLauncherServices.Execute(engine,"download",p,Report,cancel.Token);
   case "updatesGet":return ComponentEvidence.CheckUpdates(engine,cancel.Token);
   case "profileRecover":return Message(LaunchProfiles.Recover(engine,true));
   case "savesList":return SaveProfiles.List(engine);
   case "modCatalog":return SaveProfiles.Catalog(engine);
   case "modCover":return SaveProfiles.Cover(engine,Text(p,"token"));
   case "javaList":return JavaApprovals.List(engine);
   case "javaSave":Check();object decision;if(!p.TryGetValue("decision",out decision)||!(decision is bool))throw new Exception("必须明确选择允许或拒绝此文件。");return JavaApprovals.Save(engine,Text(p,"stamp"),Text(p,"hash"),(bool)decision);
   case "saveGet":return SaveProfiles.Read(engine,Text(p,"id"));
   case "saveSave":Check();object requested;if(!p.TryGetValue("mods",out requested)||requested is string||!(requested is System.Collections.IEnumerable))throw new Exception("模组清单必须为数组。");var ids=((System.Collections.IEnumerable)requested).Cast<object>().Select(x=>{if(!(x is string))throw new Exception("模组标识必须为文本。");return (string)x;}).ToArray();return SaveProfiles.Save(engine,Text(p,"id"),Text(p,"stamp"),ids,Flag(p,"confirmed"));
   case "serverList":return servers.List();
   case "serverUpsert":return servers.Upsert(p);
   case "serverDelete":return servers.Delete(Text(p,"id"),Text(p,"stamp"));
   case "serverQuery":return servers.Query(Text(p,"id"),cancel.Token);
   case "profileLaunch":if(test)throw new Exception("测试模式禁止真实游戏启动。");string targetKind=Text(p,"kind"),targetId=Text(p,"id");var launchRequest=new ProfileLaunchRequest{Kind=targetKind,Id=targetId};if(targetKind=="save"){SaveProfiles.ValidateForLaunch(engine,targetId);string savePath=SaveProfiles.ResolveSave(engine,targetId);launchRequest.Mode=Directory.GetParent(savePath).Name;launchRequest.Save=Path.GetFileName(savePath);}else if(targetKind=="server"){var target=servers.Target(targetId);launchRequest.Host=target.Host;launchRequest.Port=target.Port;launchRequest.Username=target.Username;launchRequest.UserPassword=target.UserPassword;launchRequest.ServerPassword=target.ServerPassword;launchRequest.UseSteamRelay=target.UseSteamRelay;}else throw new Exception("未知启动目标。");object launchResult=LaunchProfiles.Launch(engine,launchRequest);string tracking=PlaytimeTracker.Start(engine);return new{message=new JavaScriptSerializer().Serialize(launchResult)+"\n"+tracking};
   case "setGame":string path=Path.GetFullPath(Text(p,"path"));LauncherMaintenance.NoReparse(path);if(Running())throw new Exception("请退出游戏后选择目录。");if(!File.Exists(Path.Combine(path,"ProjectZomboid64.json"))||!File.Exists(Path.Combine(path,"ProjectZomboid64.exe")))throw new Exception("游戏目录不完整。");string preference=Path.Combine(data,"game-path.txt");LauncherMaintenance.NoReparse(preference);Directory.CreateDirectory(data);string preferenceTemp=preference+".new-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(preferenceTemp,path,new UTF8Encoding(false));if(File.Exists(preference))File.Replace(preferenceTemp,preference,null);else File.Move(preferenceTemp,preference);}finally{if(File.Exists(preferenceTemp))File.Delete(preferenceTemp);}SetEngine(path);return Status();
   case "componentsAction":string component=Text(p,"component"),operation=Text(p,"operation");string componentResult=Components(component,operation,p);if(operation!="uninstall"&&component!="all"&&!componentResult.Contains("[失败]"))ComponentEvidence.Record(engine,component);return Message(componentResult);
   case "memoryGet":return MemoryGet();
   case "memorySave":Check();string stamp=Text(p,"stamp");if(!memorySnapshots.Contains(stamp)||stamp!=LaunchStamp())throw new Exception("启动配置已改变，请重新读取内存后核对。");object raw;if(!p.TryGetValue("value",out raw)||!(raw is int))throw new Exception("内存必须为整数 GiB。");return Message(LauncherMaintenance.SetHeapGiB(engine,(int)raw));
   case "settingsGet":return SettingsGet();
   case "settingsSave":Check();string ss=Text(p,"stamp");ViewpointSettings settings;if(!settingSnapshots.TryGetValue(ss,out settings)||ss!=SettingsStamp()||settings.Changed())throw new Exception("设置已改变，请重新读取并核对。");object values;if(!p.TryGetValue("values",out values)||!(values is Dictionary<string,object>))throw new Exception("设置值格式无效。");var edits=new Dictionary<string,string>();foreach(var pair in (Dictionary<string,object>)values){if(!(pair.Value is string))throw new Exception("设置值必须为文本。");edits.Add(pair.Key,(string)pair.Value);}return Message(settings.Save(edits,Running()));
   case "shadersGet":return ShadersGet();
   case "shaderSelect":Check();string sh=Text(p,"stamp");ShaderSelection shader;if(!shaderSnapshots.TryGetValue(sh,out shader)||sh!=ShaderStamp())throw new Exception("光影包或配置已改变，请重新读取后选择。");return Message(shader.Select(Text(p,"id"),Running()));
   case "importShader":Check();string zip=Path.GetFullPath(Text(p,"path"));LauncherMaintenance.NoReparse(zip);if(!zip.EndsWith(".zip",StringComparison.OrdinalIgnoreCase))throw new Exception("请选择光影 ZIP。");LauncherMaintenance.NoReparse(engine.ShaderDir);return Message(engine.Import(zip));
   case "maintenance":Confirm(p);Check();string kind=Text(p,"kind");if(kind=="cache")return Message(LauncherMaintenance.ClearMultiplayerCache(engine));if(kind=="workshop")return Message(LauncherMaintenance.RebuildWorkshop(engine,(v,t)=>Report(v,t),cancel.Token));throw new Exception("未知维护操作。");
   case "launch":if(test)throw new Exception("测试模式禁止启动游戏。");string reason=LauncherLaunch.Reason(engine,false,Running());if(reason!="")throw new Exception(reason);Check();Links.Open("steam://rungameid/108600");return Message("已向 Steam 发送启动请求，实际状态以游戏进程为准。\n"+PlaytimeTracker.Start(engine));
   case "theme":string theme=Text(p,"value");if(theme!="dark"&&theme!="light")throw new Exception("未知主题。");LauncherMaintenance.NoReparse(data);LauncherTheme.Create(theme=="light").Save(data);return new{theme=theme};
   case "help":return new{body=ModernHelp()+"\r\n\r\n"+ProfileGuide(),rights=LegalContent.Statement+LegalContent.OptionalCredits,recovery=engine.ManualGuide(),dlss="DLSS 5 为实验性第三方组合，未游戏内验证；可在此启用／停用，非 NVIDIA 官方支持声明。",sources=new[]{"https://github.com/jlrouzies-fr/DLSS5-Feeder","https://reshade.me/","https://github.com/umar-afzaal/LumeniteFX"}};
   case "logs":return new{entries=log.ToArray(),logPath=Path.Combine(data,"diagnostics"),backupPath=Path.Combine(data,"backups")};
   case "reticleGet":var reticle=ReticleSettings.Load(data);return new{startNative=reticle.StartNative,keyText=reticle.KeyText};
   case "reticleSave":Check();var aim=new ReticleSettings{StartNative=Flag(p,"startNative"),KeyText=Text(p,"keyText")};aim.Properties("validation");LauncherMaintenance.NoReparse(data);aim.Save(data);if(new PresentationBridge().Enabled(engine))return Message(new PresentationBridge().Enable(engine,InstallWorkflow.Source(engine,ShootClient.Item)));return Message("原版瞄准回退设置已保存；枪械安装时应用。");
   case "open":return Open(Text(p,"target"));
   case "openOfficial":string item=Text(p,"item");ulong id;if(!ulong.TryParse(item,out id)||!WorkshopWorker.AllowItem(id))throw new Exception("未知作者条目。");if(test)throw new Exception("测试模式禁止打开外部页面。");Links.Open("https://steamcommunity.com/sharedfiles/filedetails/?id="+id);return Message("已打开作者工坊页面。");
   case "dlss":Confirm(p);Check();string op=Text(p,"operation");var installer=new DlssInstaller(engine.Game,data,test){Progress=(v,t)=>Report(v,t)};if(op=="disable")return Message(installer.Disable());if(op!="enable")throw new Exception("未知 DLSS 操作。");if(test)throw new Exception("测试模式禁止真实下载 DLSS。");string cache=ComponentCache.Prepare(Path.Combine(data,"DLSS-Cache"),(v,t)=>Report(-1,t),cancel.Token);Check();return Message(installer.Enable(cache));
   default:throw new Exception("未允许的操作："+action);
  }}
  string ModernHelp(){return "点击组件卡片安装／卸载；基础组件卸载会关闭依赖它的物件、枪械、汉化。各可选组件独立处理失败结果。\r\n\r\n"+StartupHelp.Body(user).Replace("主页面勾选需要的组件，点“安装”","在组件卡片点击“安装”").Replace("主页面勾选“游戏内中文（老余汉化）”并安装","在中文组件卡片点击安装").Replace("卸载：只勾选不要的组件，点“卸载”。勾选基础 3D 时会连带关闭枪械和汉化；只卸载枪械请取消其余勾选。","卸载：在对应组件卡片点击卸载；基础 3D 卸载时会连带关闭依赖组件。")+"\r\nJava 授权：逐项核对已安装模组及作者，勾选 Allow、Save decisions to disk 后确认；无需 Trust author。名称空白或来源未知请取消并检查日志。本工具不会代替授权。";}
  static string ProfileGuide(){using(var input=typeof(Program).Assembly.GetManifestResourceStream("Profiles.Guide.md")){if(input==null)return "存档与服务器功能说明见软件旁的使用说明。";using(var reader=new StreamReader(input,Encoding.UTF8))return reader.ReadToEnd();}}
  object Open(string target){string path;switch(target){case "game":path=engine.Game;break;case "logs":path=Path.Combine(data,"diagnostics");break;case "shaders":path=engine.ShaderDir;break;case "backups":path=Path.Combine(data,"backups");break;case "notices":path=BundledAssets.NoticePath;break;default:throw new Exception("未允许的目录。");}if(!Directory.Exists(path))throw new Exception("目录尚不存在："+path);if(test)throw new Exception("测试模式禁止打开外部程序。");Links.Open(path);return Message("已打开目录。");}
  static string HashPaths(IEnumerable<string> paths){var b=new StringBuilder();foreach(string path in paths.Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase)){LauncherMaintenance.NoReparse(path);b.Append(Path.GetFullPath(path)).Append(':').Append(File.Exists(path)?DlssInstaller.HashFile(path):"missing").Append('\n');}return DlssInstaller.Hash(Encoding.UTF8.GetBytes(b.ToString()));}
  string SettingsStamp(){return HashPaths(ViewpointSettings.Files.Select(f=>Path.Combine(user,f)));}
  string ShaderStamp(){return HashPaths(new[]{Path.Combine(user,"viewpoint-live.properties")}.Concat(Directory.Exists(engine.ShaderDir)?Directory.GetFiles(engine.ShaderDir,"*.zip"):new string[0]));}
  string LaunchStamp(){var files=new List<string>{engine.Config,Path.Combine(engine.Game,"ProjectZomboid32.json"),Path.Combine(engine.Game,"ProjectZomboid64.bat"),Path.Combine(engine.Game,"ProjectZomboid32.bat"),engine.Mods};if(Directory.Exists(engine.Game))files.AddRange(Directory.GetFiles(engine.Game,"ProjectZomboid*.json").Concat(Directory.GetFiles(engine.Game,"ProjectZomboid*.bat")));return DlssInstaller.Hash(Encoding.UTF8.GetBytes(HashPaths(files)+"\n"+engine.ReadSteamOptions().ScopedStamp));}
  object MemoryGet(){string stamp=LaunchStamp();int current=LauncherMaintenance.ReadHeapGiB(engine);var info=LauncherMaintenance.MemoryInfo();if(stamp!=LaunchStamp())throw new Exception("读取期间启动配置改变，请重试。");memorySnapshots.Add(stamp);return new{currentGiB=current,totalGiB=info.TotalGiB,availableGiB=info.AvailableGiB,maximumGiB=info.MaximumHeapGiB,recommendedGiB=info.RecommendedHeapGiB,stamp=stamp};}
  object SettingsGet(){string stamp=SettingsStamp();var snapshot=new ViewpointSettings(user,Path.Combine(data,"backups"));if(stamp!=SettingsStamp()||snapshot.Changed())throw new Exception("读取期间设置改变，请重试。");settingSnapshots[stamp]=snapshot;return new{stamp=stamp,rows=snapshot.Values.Select(p=>{string key=p.Key.Split('|')[1];var info=SettingsCatalog.Find(key);return new{key=p.Key,name=info==null?key:info.Name,group=SettingsCatalog.Group(key),description=SettingsCatalog.Description(key),kind=info==null?"readonly":info.Kind,choices=info==null?null:info.Choices,value=p.Value,editable=info!=null&&info.Kind!="readonly"};}).ToArray(),warnings=snapshot.Values.Count==0?new[]{"尚未生成实际设置文件；请进入游戏后再读取。"}:new string[0]};}
  object ShadersGet(){string stamp=ShaderStamp();var snapshot=new ShaderSelection(user,Path.Combine(data,"backups"));if(stamp!=ShaderStamp()||snapshot.Changed())throw new Exception("读取期间光影改变，请重试。");shaderSnapshots[stamp]=snapshot;return new{selected=snapshot.Selected,packs=snapshot.Packs.Select(p=>new{id=p.Id,name=p.Name,description=p.Description,valid=p.Valid,file=p.File}).ToArray(),stamp=stamp};}
  bool Mod(string id){return File.Exists(engine.Mods)&&Regex.IsMatch(File.ReadAllText(engine.Mods),@"(?m)^\s*mod\s*=\s*"+Regex.Escape(id)+@"\s*,");}
  bool ValidComponent(string id){try{switch(id){case "base":return engine.HasView&&File.Exists(Path.Combine(engine.BuddyLib,"ZombieBuddy.jar"))&&File.Exists(Path.Combine(engine.BuddyLib,"zbNative.dll"));case "models":return engine.HasModels;case "shoot":ShootClient.Validate(InstallWorkflow.Source(engine,ShootClient.Item));return true;case "chinese":ChinesePatch.Validate(InstallWorkflow.Source(engine,ChinesePatch.Item));return true;}}catch{}return false;}
  object Status(){ApplySources();return new{gamePath=engine.Game,validGame=File.Exists(engine.Config)&&File.Exists(Path.Combine(engine.Game,"ProjectZomboid64.exe")),running=Running(),configured=engine.Enabled,buddyFiles=File.Exists(Path.Combine(engine.Game,"ZombieBuddy.jar"))&&File.Exists(Path.Combine(engine.Game,"zbNative.dll")),theme=LauncherTheme.Load(data).Light?"light":"dark",launch=LaunchProfiles.State(engine),hardware=test?HardwareProbe.Unknown():HardwareProbe.Cached(),task=new{active=false,value=progressValue,text=progressText},components=Cards(new[]{Card("base","基础 3D + Buddy","Viewpoint 与原生 Buddy 加载器；配置完成后需游戏内授权和验证。","3809306528",engine.Enabled),Card("models","额外 3D 物件","PZVoxelStudioViewpoint 物件模型，需要基础组件。","3810302175",Mod("PZVoxelStudioViewpoint")),Card("shoot","第一人称枪械瞄准","Shoot to Thrill 多人版及适用的本地瞄准回退补丁。","3813032735",ShootClient.Enabled(engine)),Card("chinese","游戏内中文","老余汉化 JAVA 版；需简体中文并批准 laoyu.javacn。","3810637496",ChinesePatch.Enabled(engine))}),configStamp=HashPaths(new[]{engine.Config,engine.Mods}.Concat(ViewpointSettings.Files.Select(f=>Path.Combine(user,f))))};}
  object[] Cards(object[] core){var result=core.Select(c=>{string key=Convert.ToString(new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(c))["id"]);return (object)ComponentEvidence.Decorate(engine,key,c);}).ToList();foreach(var a in ViewpointAddons.All){bool downloaded=false,preload=false;string version="未下载",warning=a.Warning;try{var f=ViewpointAddons.Find(engine,a);downloaded=true;preload=ViewpointAddons.Preload(f);string v;if(f.Metadata.TryGetValue("modversion",out v)||f.Metadata.TryGetValue("version",out v))version=v;else version="作者未声明版本";}catch(Exception ex){warning+=(warning==""?"":" ") +ex.Message;}var card=new{id=a.Key,title=a.Title,description=a.Description,item=a.Item.ToString(),downloaded=downloaded,configured=ViewpointAddons.Enabled(engine,a),version=version,optional=true,preload=preload,warning=warning,compatibility=preload?"作者声明客户端预加载；多人仍需实测":"普通本地启用；未保证服务器替换清单后保留加载",retirement="尚无已核实的本体合并公告，不自动停用"};result.Add(ComponentEvidence.Decorate(engine,a.Key,card));}return result.ToArray();}
  object Card(string id,string title,string description,string item,bool configured){return new{id=id,title=id=="models"?"6244 3D Models · 物件模型":title,description=description,item=item,downloaded=ValidComponent(id),configured=configured,optional=id!="base"&&id!="chinese",version=LocalVersion(engine,id,ulong.Parse(item))};}
  static string LocalVersion(Engine e,string key,ulong item){try{string id=key=="base"?"Viewpoint":key=="models"?"PZVoxelStudioViewpoint":key=="shoot"?ShootClient.Id:ChinesePatch.Id;var files=ViewpointAddons.Find(e,new ViewpointAddon(key,item,id,key,""));string value;if(files.Metadata.TryGetValue("modversion",out value)||files.Metadata.TryGetValue("version",out value))return value;}catch{}return "本地版本未声明／来源待核对";}
  Dictionary<ulong,string> Download(Engine e,ulong[] ids,Action<int,string> progress,CancellationToken token,bool update){if(test)throw new Exception("测试模式禁止真实工坊下载。");if(!update)return WorkshopWorker.Fetch(e.Game,ids,progress,token,false);var plan=WorkshopUpdate.Check(e,ids,token);if(plan.Needed.Count>0){var downloaded=WorkshopWorker.Fetch(e.Game,plan.Needed.ToArray(),progress,token,true);foreach(var p in downloaded)plan.Paths[p.Key]=p.Value;}return plan.Paths;}
  Dictionary<ulong,string> Fetch(ulong[] ids,bool update){Check();var paths=fetch(engine,ids,(v,t)=>Report(v,t),cancel.Token,update);cancel.Token.ThrowIfCancellationRequested();if(paths==null||ids.Any(id=>!paths.ContainsKey(id)||!Directory.Exists(paths[id])))throw new Exception("下载结果缺少完整条目。");InstallWorkflow.Apply(engine,paths);LauncherMaintenance.NoReparse(data);Directory.CreateDirectory(data);string record=Path.Combine(data,"workshop-paths.json");LauncherMaintenance.NoReparse(record);var all=File.Exists(record)?new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(record)):new Dictionary<string,string>();foreach(var pair in paths)all[pair.Key.ToString()]=pair.Value;File.WriteAllText(record,new JavaScriptSerializer().Serialize(all),new UTF8Encoding(false));return paths;}
  string InstallBase(){Check();bool keepModels=Mod("PZVoxelStudioViewpoint");string result=InstallWorkflow.Enable(engine,keepModels,ids=>Fetch(ids,false));string live=Path.Combine(user,"viewpoint-live.properties");bool hasChoice=File.Exists(live)&&new PropertyDocument(File.ReadAllBytes(live)).Values.ContainsKey("graphics.pack");if(!hasChoice&&File.Exists(Path.Combine(engine.ShaderDir,ShaderSelection.EclipseFile)))result+="\r\n"+new ShaderSelection(user,Path.Combine(data,"backups")).DefaultOnce(Path.Combine(data,"shader-default-installed.txt"),Running());return result;}
  string InstallOptional(string id){Check();if(id=="models"){if(!ValidComponent(id))Fetch(new[]{3810302175UL},false);return Models(true);}if(id=="shoot"){if(!ValidComponent(id))Fetch(new[]{ShootClient.Item},false);string source=InstallWorkflow.Source(engine,ShootClient.Item);return new ShootClient().Enable(engine,source)+"\r\n"+new PresentationBridge().Enable(engine,source);}if(id=="chinese"){if(!ValidComponent(id))Fetch(new[]{ChinesePatch.Item},false);return new ChinesePatch().Enable(engine,InstallWorkflow.Source(engine,ChinesePatch.Item));}if(ViewpointAddons.All.Any(a=>a.Key==id)){var a=ViewpointAddons.Get(id);try{ViewpointAddons.Find(engine,a);}catch{Fetch(new[]{a.Item},false);}return ViewpointAddons.Switch(engine,id,true);}throw new Exception("未知组件。");}
  string Batch(IEnumerable<string> ids,Func<string,string> work){var result=new List<string>();foreach(string id in ids){cancel.Token.ThrowIfCancellationRequested();try{result.Add("[完成] "+id+"\r\n"+work(id));}catch(OperationCanceledException){throw;}catch(Exception ex){result.Add("[失败] "+id+"\r\n"+ex.Message);}}return string.Join("\r\n\r\n",result);}
  string Components(string id,string op,Dictionary<string,object> p){if(!new[]{"base","models","shoot","chinese","all"}.Contains(id)&&!ViewpointAddons.All.Any(a=>a.Key==id)||!new[]{"install","uninstall","update"}.Contains(op))throw new Exception("未知组件或操作。");Check();if(File.Exists(Path.Combine(data,"workshop-rebuild.pending")))throw new Exception("工坊重新下载尚未完成，请先重试维护任务。");if(op=="uninstall"){if((id=="base"||id=="all"||id=="roofs")&&Mod("ViewpointTileFix")&&!Flag(p,"roofRemovalAcknowledged"))throw new Exception("完整屋顶可能有已保存标记，请先按作者说明清理，并明确确认屋顶移除提示。");if(id=="base"||id=="all"){Confirm(p);string extras=Batch(ViewpointAddons.All.Where(a=>ViewpointAddons.Enabled(engine,a)).Select(a=>a.Key),a=>ViewpointAddons.Switch(engine,a,false));return extras+"\r\n"+engine.Switch(false,false);}if(ViewpointAddons.All.Any(a=>a.Key==id))return ViewpointAddons.Switch(engine,id,false);return id=="models"?Models(false):id=="shoot"?new ShootClient().Disable(engine):new ChinesePatch().Disable(engine);}
   if(op=="install"){if(id=="base")return InstallBase();string basis=ShootClient.BaseReady(engine)&&engine.HasView?"基础组件已配置。":InstallBase();return basis+"\r\n"+Batch(id=="all"?new[]{"models","shoot","chinese"}:new[]{id},InstallOptional);}
   return Batch(id=="all"?new[]{"base","models","shoot","chinese"}:new[]{id},Update);
  }
  string Update(string id){Check();if(ViewpointAddons.All.Any(a=>a.Key==id)){var a=ViewpointAddons.Get(id);bool on=ViewpointAddons.Enabled(engine,a);Fetch(new[]{a.Item},true);return on?ViewpointAddons.Switch(engine,id,true):"作者文件已核对；仍保持未启用。";}bool enabled=id=="base"?engine.Enabled:id=="models"?Mod("PZVoxelStudioViewpoint"):id=="shoot"?ShootClient.Enabled(engine):ChinesePatch.Enabled(engine);bool bridge=new PresentationBridge().Enabled(engine);Fetch(id=="base"?InstallWorkflow.Requested(false):new[]{id=="models"?3810302175UL:id=="shoot"?ShootClient.Item:ChinesePatch.Item},true);if(bridge&&(id=="base"||id=="shoot"))new PresentationBridge().Disable(engine);string result=enabled?(id=="base"?InstallBase():InstallOptional(id)):"作者文件已核对；原本未启用，保留关闭状态。";if(bridge&&id=="base")result+="\r\n"+new PresentationBridge().Enable(engine,InstallWorkflow.Source(engine,ShootClient.Item));return result;}
  string Models(bool on){Check();if(on&&!ShootClient.BaseReady(engine))throw new Exception("请先安装基础 3D 和 Buddy。");LauncherMaintenance.NoReparse(engine.Mods);if(!File.Exists(engine.Mods))return "物件模型未启用。";byte[] before=File.ReadAllBytes(engine.Mods);string text=Encoding.UTF8.GetString(before).TrimStart('\uFEFF');var block=Regex.Match(text,@"\bmods\s*\{(?<body>[^}]*)\}");if(!block.Success)throw new Exception("模组列表格式无法识别。");string body=Regex.Replace(block.Groups["body"].Value,@"(?m)^[ \t]*mod\s*=\s*PZVoxelStudioViewpoint\s*,[^\r\n]*(?:\r?\n|$)","");if(on)body=body.TrimEnd()+"\r\n    mod = PZVoxelStudioViewpoint,\r\n";string next=text.Substring(0,block.Groups["body"].Index)+body+text.Substring(block.Groups["body"].Index+block.Groups["body"].Length);if(next==text)return "物件模型状态已保持。";string backup=Path.Combine(data,"backups","models-"+Guid.NewGuid().ToString("N"));LauncherMaintenance.NoReparse(backup);Directory.CreateDirectory(backup);File.WriteAllBytes(Path.Combine(backup,"default.txt"),before);File.WriteAllText(Path.Combine(backup,"人工恢复物件模型.txt"),"退出游戏后仅添加／移除 default.txt 的 PZVoxelStudioViewpoint 行。整份恢复会覆盖后续更改。原路径："+engine.Mods);string temp=engine.Mods+".modern-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,next,new UTF8Encoding(false));Check();if(!File.ReadAllBytes(engine.Mods).SequenceEqual(before))throw new Exception("模组列表已改变，拒绝覆盖。");File.Replace(temp,engine.Mods,null);}finally{if(File.Exists(temp))File.Delete(temp);}return (on?"已启用物件模型。":"已停用物件模型，保留其他组件。")+"\r\n备份："+backup;}
  internal static readonly HashSet<string> NativeReads=new HashSet<string>{"status","memoryGet","settingsGet","shadersGet","help","logs","reticleGet","savesList","modCatalog","saveGet","serverList","modCover","javaList","updatesGet","modProfiles","modProfileGet","modSort","saveThumb","serverThumb","taskGet","playtimeGet","serverFavorites","steamConnection","steamSubscriptions","steamSearch","steamDetails","serverHall"};
  static string[] ModArray(Dictionary<string,object> p){object raw;if(!p.TryGetValue("mods",out raw)||raw is string||!(raw is System.Collections.IEnumerable))throw new Exception("模组清单必须为数组。");return ((System.Collections.IEnumerable)raw).Cast<object>().Select(o=>{if(!(o is string))throw new Exception("模组标识必须为文本。");return (string)o;}).ToArray();}
  static string SafeResultMessage(object result,string title){if(result!=null){var property=result.GetType().GetProperty("message");if(property!=null){var message=property.GetValue(result,null) as string;if(message!=null)return LauncherJournal.Sanitize(message);}var map=result as Dictionary<string,object>;object value;if(map!=null&&map.TryGetValue("message",out value)&&value is string)return LauncherJournal.Sanitize((string)value);}return title+" · 操作完成；请在对应页面核对当前状态。";}
  static string TaskTitle(string action,Dictionary<string,object> p){if(action=="maintenance"){object kind;if(p!=null&&p.TryGetValue("kind",out kind))return Convert.ToString(kind)=="cache"?"清除多人缓存":"重新下载创意工坊模组";}var titles=new Dictionary<string,string>{{"componentsAction","处理模组组件"},{"memorySave","保存游戏内存"},{"settingsSave","保存 Viewpoint 画面设置"},{"profileLaunch","启动指定存档或服务器"},{"launch","启动游戏"},{"steamDownload","订阅并下载工坊模组"},{"modProfileActivate","启用模组配置"},{"modProfileSave","保存模组配置"},{"saveSave","保存存档模组清单"},{"playtimeSettings","设置游玩提醒"},{"favoriteImport","导入原版服务器收藏"}};string title;return titles.TryGetValue(action,out title)?title:action;}
  public void Dispose(){lock(gate){disposed=true;cancel.Cancel();foreach(var request in networkRequests)request.Cancel();if(!busy)cancel.Dispose();}}
